Definition r_AST_59_0000 : list (option Trans) := [t1RB;t1LD;t1LC;t0RA;t0LD;t0LB;t1RD;t0RB].
Lemma cv_AST_59_0000 : coversTr (row_to_tm r_AST_59_0000).
Proof. assert(Hmanual:forall N,exists j e,N<=j /\
    stepn (row_to_tm r_AST_59_0000) j InitES=Some e /\instr_of e=(StA,S1)).
  { eapply paired_carry_A1_recurrent with (qa:=StA)(qb:=StB)(qc:=StC)(qd:=StD);try reflexivity.
    exists 20,[],1,0. rewrite <-lift_c0. apply csteps_lift. vm_compute. reflexivity. }
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 3 0 2560 18 skip_AST_59_0000 cert_AST_59_0000).
  - intros [[] []]H N;try discriminate.
    destruct(Hmanual N)as(j&e&Hj&He&Hi). exists j. split;[exact Hj|].
    apply mirror_fires. exists e. auto.
  - vm_compute. reflexivity. Qed.

